mapper.update:
UPDATE monitor_snapshot SET health_status=#{healthStatus}, health_detail=#{healthDetail},
    process_status=#{processStatus}, process_pid=#{processPid}, cpu_percent=#{cpuPercent},
    memory_mb=#{memoryMb}, heap_used_mb=#{heapUsedMb}, heap_max_mb=#{heapMaxMb},
    gc_count=#{gcCount}, gc_time_ms=#{gcTimeMs}, response_ms=#{responseMs},
    host_cpu_percent=#{hostCpuPercent}, host_memory_percent=#{hostMemoryPercent},
    disk_usage_percent=#{diskUsagePercent}, extra_json=#{extraJson}, collect_time=#{collectTime}
WHERE id=#{id}
AND tenant_id = #{tenantId}

mapper.select:
SELECT m.* FROM monitor_snapshot m
INNER JOIN (
    SELECT node_id, MAX(collect_time) AS max_time FROM monitor_snapshot
    WHERE project_id = #{projectId} GROUP BY node_id
) t ON m.node_id = t.node_id AND m.collect_time = t.max_time AND m.project_id = #{projectId}

SELECT s.* FROM monitor_snapshot s INNER JOIN ( SELECT node_id, MAX(collect_time) AS max_time FROM monitor_snapshot WHERE node_id IN
#{nid}
GROUP BY node_id ) t ON s.node_id = t.node_id AND s.collect_time = t.max_time

SELECT s.* FROM monitor_snapshot s INNER JOIN ( SELECT project_id, node_id, MAX(collect_time) AS max_time FROM monitor_snapshot WHERE node_id IN
#{nid}
GROUP BY project_id, node_id ) t ON s.project_id = t.project_id AND s.node_id = t.node_id AND s.collect_time = t.max_time

SELECT * FROM monitor_snapshot
WHERE project_id = #{projectId}
AND node_id = #{nodeId}
AND collect_time >= #{startTime}
AND collect_time <= #{endTime}
ORDER BY collect_time ASC
LIMIT #{limit}

SELECT * FROM monitor_snapshot
WHERE project_id = #{projectId}
AND node_id = #{nodeId}
ORDER BY collect_time DESC
LIMIT #{limit}

SELECT COUNT(*) FROM monitor_snapshot
WHERE project_id = #{projectId}
AND node_id = #{nodeId}
AND health_status = 'DOWN' AND collect_time >= #{startTime}
